.courses-v26__overview {
    .courses-v26__overview__heading {
        margin-bottom: $measure--small4;
    }

    // overview - accredidation styles
    .wrapper--logo {
        max-width: $max-line-length;
    }

    .courses-v26__overview__content--2cols {
        display: flex;
        flex-direction: row;
        gap: $measure--small4;

        @include media('<between') {
            flex-direction: column;
        }

        > div {
            flex: 1;
        }
    }
}

// Floating Apply Button styles
.courses-v26__floating-apply {
    position: fixed;
    right: $measure--small4;
    bottom: $measure--small4;
}

.courses-v26__floating-apply__link {
    @include cta-reset('\f061');
    border: $border-width-default $border-style-solid $color-purewhite;
    background: $color-brand-primary;
    color: $color-bg;

    &:visited {
        color: $color-bg;
        border-color: $color-purewhite;
    }

    &:focus {
        background: $color-brand-primary;
        color: $color-bg;
    }

    &:active,
    &:focus {
        @include anchor-default-outline($color-outline--dark);
        border-color: $color-brand-primary;
    }

    &:hover,
    &:active {
        @include media('hover') {
            border-color: $color-purewhite;
            background-image: none;
            background: $color-red70;
        }
    }
}

.courses-v26 {
    // Entry requirements dropdown filter styles
    .dropdown-filter__wrap {
        display: flex;
        flex-direction: row;
        gap: $measure--half;
    }

    .dropdown-filter {
        margin-top: 0;
    }

    .dropdown-filter__select {
        margin-top: 0;
        position: inherit;
        line-height: inherit;
        border: $border-width-hairline $border-style-solid $color-nearblack;
        height: inherit;
    }

    .dropdown-filter__label {
        align-self: center;
        margin-top: 0;
        font-weight: $font-weight-medium;
    }

    // Hide tab panel headins as not in design - we still need this for screen readers?
    .tabs__panel__heading {
        display: none;
    }

    .tabs__panel__body--qualification,
    .tabs__panel__body--eng-lan-req {
        display: grid;
        @include content-grid();
        grid-column-gap: $measure--half;
    }

    .tabs__col-1-3 {
        grid-column: 1 / span 6;

        @include media('<small') {
            grid-column: 1 / -1;
        }
    }

    .tabs__col-2-3 {
        grid-column: 7 / span 12;

        @include media('<small') {
            grid-column: 1 / -1;
        }
    }
}
